internal object ProjectsUpdateProjectDomainOperation {
    /**
     * Updates a project domain’s configuration, including its Git branch association and redirect settings. Supply only the configuration fields you want to change; `redirectStatusCode` accepts 301, 302, 307, 308, or null.
     *
     * Update a project domain's configuration, including the name, git branch and redirect of the domain.
     *
     * @param idOrName The unique project identifier or the project name
     * @param domain The project domain name
     * @param teamId The Team identifier to perform the request on behalf of.
     * @param slug The Team slug to perform the request on behalf of.
     * @param gitBranch Git branch to link the project domain
     * @param redirect Target destination domain for redirect
     * @param redirectStatusCode Status code for domain redirect
     */
    fun updateProjectDomain(clientConfig: ClientConfig, request: Projects.UpdateProjectDomainRequest, options: RequestOptions? = null): Projects.UpdateProjectDomainResponse {
        validateUpdateProjectDomainRequest(request)

        return SdkClient.request<Projects.UpdateProjectDomainResponse>(SdkClient.RequestSpec("PATCH", "/v9/projects/${SdkClient.encodePathSegment(request.idOrName)}/domains/${SdkClient.encodePathSegment(request.domain)}", config = clientConfig, query = mapOf("teamId" to
    SdkClient.queryValue(request.teamId, "form", true), "slug" to SdkClient.queryValue(request.slug, "form", true)), body = SdkClient.bodyMap("gitBranch" to
    (request.gitBranch ?: SdkClient.SdkOptional.Omitted), "redirect" to
    (request.redirect ?: SdkClient.SdkOptional.Omitted), "redirectStatusCode" to
    (request.redirectStatusCode ?: SdkClient.SdkOptional.Omitted)), operationId = "updateProjectDomain", decoder = SdkClient.ResponseDecoder.JSON, options = options)).data
    }


    private fun validateUpdateProjectDomainRequest(request: Projects.UpdateProjectDomainRequest) {
        val gitBranchValue = request.gitBranch?.getOrNull()
if (gitBranchValue != null) {
            Validation.validateLength("gitBranch", gitBranchValue, Validation.LengthOpts(max = 250))
}
    }
}
